121	    /**
122	     * Resolve the city for a newly created owner. If an owner already exists in
123	     * that city (matched case-insensitively), reuse that owner's exact spelling;
124	     * otherwise the supplied city is title-cased.
125	     */
126	    private String resolveCity(String city) {
127	        if (city == null) {
128	            return null;
129	        }
130	        return this.clinicService.findAllOwners().stream()
131	            .map(Owner::getCity)
132	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
133	            .findFirst()
134	            .orElseGet(() -> titleCase(city));
135	    }
