137	    /**
138	     * Title-case a city name: the first letter of each whitespace-separated word
139	     * is upper-cased and the remaining letters lower-cased.
140	     */
141	    private String titleCase(String city) {
142	        StringBuilder sb = new StringBuilder(city.length());
143	        boolean startOfWord = true;
144	        for (int i = 0; i < city.length(); i++) {
145	            char c = city.charAt(i);
146	            if (Character.isWhitespace(c)) {
147	                startOfWord = true;
148	                sb.append(c);
149	            } else if (startOfWord) {
150	                sb.append(Character.toUpperCase(c));
151	                startOfWord = false;
152	            } else {
153	                sb.append(Character.toLowerCase(c));
154	            }
155	        }
156	        return sb.toString();
