164	
165	    /**
166	     * Resolve the membership tier for a newly created owner: the first
167	     * {@link #FOUNDING_MEMBERSHIP_LIMIT} owners ever created are 'FOUNDING' and
168	     * all later owners are 'STANDARD'.
169	     */
170	    private String resolveMembershipTier() {
171	        long existingOwners = this.clinicService.findAllOwners().size();
172	        return existingOwners < FOUNDING_MEMBERSHIP_LIMIT ? "FOUNDING" : "STANDARD";
173	    }
