175	    /**
176	     * Build the customer code for a newly created owner, formatted as
177	     * '<UPPERCASE_CITY>-<NNNN>' where NNNN is one more than the number of owners
178	     * that already exist in that city, zero-padded to four digits.
179	     */
180	    private String buildCustomerCode(String city) {
181	        long ownersInCity = this.clinicService.findAllOwners().stream()
182	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
183	            .count();
184	        return String.format("%s-%04d", city.toUpperCase(), ownersInCity + 1);
