216	     * Resolve the locality for a newly created owner: 'local' if the owner's city
217	     * is the single most common city among the owners that already exist at the
218	     * moment the new owner is created, otherwise 'remote'. Cities are compared
219	     * case-insensitively. If no owners yet exist, or two or more cities are tied
220	     * for the most common, there is no single most common city and the result is
221	     * 'remote'.
222	     */
223	    private String resolveLocality(String city) {
224	        if (city == null) {
225	            return "remote";
226	        }
227	        Map<String, Long> countsByCity = this.clinicService.findAllOwners().stream()
228	            .map(Owner::getCity)
229	            .filter(Objects::nonNull)
230	            .collect(Collectors.groupingBy(existing -> existing.toLowerCase(), Collectors.counting()));
231	        if (countsByCity.isEmpty()) {
